I'd be happy to help you set up this pathfinding logic in GDScript! It's a great idea to use a `RefCounted` class for this, as it keeps your utility functions organized without needing to manage nodes in the scene tree.

```gdscript
extends RefCounted

func neighbors(pos: Vector2i, width: int, height: int) -> Array[Vector2i]:
	var results: Array[Vector2i] = []
	# Order: up (y-1), right (x+1), down (y+1), left (x-1)
	var offsets: Array[Vector2i] = [Vector2i(0, -1), Vector2i(1, 0), Vector2i(0, 1), Vector2i(-1, 0)]

	for offset in offsets:
		var next_pos = pos + offset
		if next_pos.x >= 0 and next_pos.x < width and next_pos.y >= 0 and next_pos.y < height:
			results.append(next_pos)
	return results

func shortest_path_length(rows: Array[String], start: Vector2i, goal: Vector2i) -> int:
	if start == goal: return 0

	# Check bounds and walls
	var height = rows.size()
	var width = rows[0].length()

	var is_wall = func(p: Vector2i) -> bool:
		if p.x < 0 or p.x >= width or p.y < 0 or p.y >= height: return true
		return rows[p.y][p.x] == "#"

	if is_wall.call(start) or is_wall.call(goal): return -1

	# BFS for shortest path
	var queue: Array[Vector2i] = [start]
	var visited: Dictionary = {start: 0}

	while queue.size() > 0:
		var current = queue.pop_front()
		var dist = visited[current]

		if current == goal: return dist

		for n in neighbors(current, width, height):
			if not visited.has(n) and not is_wall.call(n):
				visited[n] = dist + 1
				queue.append(n)

	return -1
```

One common mistake is forgetting that `String` indexing in GDScript returns a character, so ensure your `rows` array is consistently sized to avoid "index out of bounds" errors.

