using UnityEngine;

public class EnemyAnimatorDriver : MonoBehaviour
{
    [Header("References")]
    [SerializeField] private Animator animator;
    [SerializeField] private Rigidbody rb;
    [SerializeField] private VoidEventChannel onHit;

    [Header("Settings")]
    [SerializeField] private float alertDistance = 5f;
    [SerializeField] private float speedDamping = 0.1f;

    private ProfilerMarker playerMarker;
    private static readonly int SpeedHash = Animator.StringToHash("Speed");
    private static readonly int AlertHash = Animator.StringToHash("Alert");
    private static readonly int HitHash = Animator.StringToHash("Hit");

    private void Awake()
    {
        // Using the Unity 6 recommended search API
        playerMarker = FindFirstObjectByType<ProfilerMarker>();
    }

    private void OnEnable()
    {
        if (onHit != null) onHit.OnEventRaised += HandleHit;
    }

    private void OnDisable()
    {
        if (onHit != null) onHit.OnEventRaised -= HandleHit;
    }

    private void Update()
    {
        if (animator == null || rb == null || playerMarker == null) return;

        // Calculate horizontal speed (x-axis)
        float horizontalSpeed = Mathf.Abs(rb.linearVelocity.x);
        animator.SetFloat(SpeedHash, horizontalSpeed, speedDamping, Time.deltaTime);

        // Check distance to player
        float distance = Vector3.Distance(transform.position, playerMarker.transform.position);
        animator.SetBool(AlertHash, distance <= alertDistance);
    }

    private void HandleHit()
    {
        if (animator != null) animator.SetTrigger(HitHash);
    }
}
